// 1. 单一职责原则（SRP）
// 反例：一个类承担多个职责
class UserManager {
    void createUser() { ... }
    void sendEmail() { ... }  // 不属于用户管理
    void generateReport() { ... }  // 不属于用户管理
}
// 正例：职责分离
class UserService {
    void createUser() { ... }
}
class EmailService {
    void sendEmail() { ... }
}
class ReportService {
    void generateReport() { ... }
}

// 2. 开闭原则（OCP）
// 反例：修改已有代码来扩展功能
class ShapeDrawer {
    void draw(Shape shape) {
        if (shape instanceof Circle) {
            drawCircle((Circle) shape);
        } else if (shape instanceof Rectangle) {
            drawRectangle((Rectangle) shape);
        }
    }
}
// 正例：通过扩展实现
interface Shape {
    void draw();
}
class Circle implements Shape {
    @Override
    public void draw() { ... }
}
class Rectangle implements Shape {
    @Override
    public void draw() { ... }
}

// 3. 里氏替换原则（LSP）
// 反例：子类改变父类行为
class Rectangle {
    protected int width;
    protected int height;
    void setWidth(int width) { this.width = width; }
    void setHeight(int height) { this.height = height; }
    int getArea() { return width * height; }
}
class Square extends Rectangle {
    @Override
    void setWidth(int width) {
        this.width = width;
        this.height = width;  // 改变了父类行为
    }
}
// 正例：使用组合或接口隔离
interface Shape {
    int getArea();
}

// 4. 接口隔离原则（ISP）
// 反例：臃肿的接口
interface Animal {
    void eat();
    void fly();
    void swim();
}
// 正例：接口隔离
interface Eatable { void eat(); }
interface Flyable { void fly(); }
interface Swimmable { void swim(); }

// 5. 依赖反转原则（DIP）
// 反例：高层依赖低层
class OrderService {
    private MySQLDao dao = new MySQLDao();  // 依赖具体实现
}
// 正例：依赖抽象
interface OrderDao { ... }
class MySQLOrderDao implements OrderDao { ... }
class OrderService {
    private OrderDao dao;  // 依赖抽象
    OrderService(OrderDao dao) {
        this.dao = dao;
    }
}
